<?php
namespace Modules\BankingMicrofinance\Http\Controllers;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\LoanGuarantor;
class GuarantorController extends Controller{public function index(){ $items=LoanGuarantor::latest()->paginate(25);return view('bankingmicrofinance::guarantors.index',compact('items'));}public function create(){return view('bankingmicrofinance::guarantors.form',['item'=>new LoanGuarantor()]);}public function store(Request $request){LoanGuarantor::create($request->all()+['created_by'=>auth()->id()]);return redirect()->route('banking-microfinance.guarantors.index')->with('status','Guarantor saved.');}public function edit(LoanGuarantor $guarantor){return view('bankingmicrofinance::guarantors.form',['item'=>$guarantor]);}public function update(Request $request,LoanGuarantor $guarantor){$guarantor->update($request->all());return redirect()->route('banking-microfinance.guarantors.index')->with('status','Guarantor updated.');}}
